head.b:skin:
/* ============================================================
NESTDEAL v3.1 — AMAZON AFFILIATE THEME (FULLY FIXED)
Fixed: Mobile overflow, image display, responsive grid, SEO, a11y
============================================================ */

:root {
  --navy: #061329;
  --navy-light: #08172E;
  --navy-dark: #040d1f;
  --orange: #FF9900;
  --orange-dark: #E68A00;
  --white: #FFFFFF;
  --bg: #F7F8FA;
  --ink: #101828;
  --ink-soft: #667085;
  --border: #E4E7EC;
  --radius: 12px;
  --radius-sm: 8px;
  --radius-xs: 6px;
  --shadow: 0 1px 3px rgba(0,0,0,.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,.08);
  --shadow-lg: 0 12px 28px rgba(0,0,0,.12);
  --font: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
  --max-w: 1240px;
  --tap-target: 44px;
}

*, *:before, *:after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;
  overflow-x: hidden;
  scroll-behavior: smooth;
  max-width: 100vw;
  width: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
  width: 100%;
  max-width: 100vw;
  position: relative;
  text-rendering: optimizeLegibility;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; -webkit-tap-highlight-color: transparent; }
ul { list-style: none; margin: 0; padding: 0; }
button {
  font-family: inherit;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

h1, h2, h3, h4 {
  font-family: var(--font);
  font-weight: 700;
  line-height: 1.2;
  margin: 0;
  color: var(--ink);
  overflow-wrap: break-word;
}

.container {
  width: 100%;
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 12px;
  min-width: 0;
}

/* ═══ BUTTONS ═══ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font);
  font-weight: 700;
  font-size: 14px;
  padding: 13px 26px;
  border-radius: var(--radius-sm);
  border: 2px solid transparent;
  cursor: pointer;
  transition: all .25s ease;
  white-space: nowrap;
  text-decoration: none;
  min-height: var(--tap-target);
  touch-action: manipulation;
}
.btn:hover { transform: translateY(-2px); box-shadow: 0 6px 18px rgba(255,153,0,.3); }
.btn:active { transform: translateY(0); }
.btn-primary { background: var(--orange); color: var(--white); border-color: var(--orange); }
.btn-primary:hover { background: var(--orange-dark); border-color: var(--orange-dark); }
.btn-outline { background: transparent; color: var(--white); border-color: rgba(255,255,255,.4); }
.btn-outline:hover { border-color: var(--white); background: rgba(255,255,255,.1); }
.btn-sm { padding: 8px 16px; font-size: 12px; border-radius: var(--radius-xs); }

/* ═══ HEADER ═══ */
.site-header { background: var(--navy); position: sticky; top: 0; z-index: 100; border-bottom: 1px solid rgba(255,255,255,.08); }
.header-top { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 14px 0; }
.brand { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
.brand-icon { width: 38px; height: 38px; background: var(--orange); border-radius: var(--radius-xs); display: flex; align-items: center; justify-content: center; font-size: 18px; color: var(--white); flex-shrink: 0; }
.brand-text { font-size: 22px; font-weight: 900; color: var(--white); letter-spacing: -.02em; }
.brand-text span { color: var(--orange); }
.search-form { flex: 1; display: flex; max-width: 520px; border: 2px solid rgba(255,255,255,.15); border-radius: var(--radius); overflow: hidden; background: rgba(255,255,255,.06); }
.search-form input { flex: 1; border: none; padding: 12px 16px; font-size: 14px; outline: none; background: transparent; color: var(--white); min-width: 0; }
.search-form input::placeholder { color: rgba(255,255,255,.5); }
.search-form button { border: none; background: var(--orange); color: var(--white); width: 48px; cursor: pointer; display: flex; align-items: center; justify-content: center; flex-shrink: 0; transition: background .2s ease; min-height: var(--tap-target); }
.search-form button:hover { background: var(--orange-dark); }
.header-right { display: flex; align-items: center; gap: 20px; flex-shrink: 0; }
.header-tagline { display: none; font-size: 12px; color: rgba(255,255,255,.65); line-height: 1.4; text-align: right; }
.header-tagline strong { color: var(--orange); }
.menu-toggle { display: flex; width: 40px; height: 40px; align-items: center; justify-content: center; border: 1.5px solid rgba(255,255,255,.2); border-radius: var(--radius-xs); background: none; cursor: pointer; color: var(--white); min-height: var(--tap-target); min-width: var(--tap-target); }
.main-nav { background: var(--navy-light); border-top: 1px solid rgba(255,255,255,.06); }
.main-nav .nav-list { display: none; gap: 8px; }
.main-nav .nav-list a { display: block; padding: 12px 16px; color: rgba(255,255,255,.7); font-size: 13.5px; font-weight: 600; transition: color .2s ease; border-radius: var(--radius-xs); }
.main-nav .nav-list a:hover { color: var(--white); background: rgba(255,255,255,.05); }

@media (min-width: 900px) {
  .search-form { display: flex; }
  .header-tagline { display: block; }
  .menu-toggle { display: none; }
  .main-nav .nav-list { display: flex; }
}

/* Mobile Drawer */
.mob-overlay { display: none; position: fixed; inset: 0; background: rgba(0,0,0,.6); z-index: 190; backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px); }
.mob-overlay.is-open { display: block; }
.mob-drawer { position: fixed; top: 0; right: -300px; left: auto; bottom: 0; width: 280px; background: var(--navy); z-index: 200; overflow-y: auto; transition: right .25s ease; box-shadow: var(--shadow-lg); }
.mob-drawer.is-open { right: 0; }
.mob-drawer-header { display: flex; align-items: center; justify-content: space-between; padding: 16px 20px; border-bottom: 1px solid rgba(255,255,255,.1); }
.mob-drawer-close { background: none; border: none; font-size: 22px; cursor: pointer; color: rgba(255,255,255,.7); min-height: var(--tap-target); min-width: var(--tap-target); }
.mob-drawer-nav a { display: block; padding: 14px 20px; color: rgba(255,255,255,.85); font-size: 14px; font-weight: 600; border-bottom: 1px solid rgba(255,255,255,.08); transition: color .2s, background .2s; }
.mob-drawer-nav a:hover { color: var(--orange); background: rgba(255,255,255,.05); }

/* ═══ HERO ═══ */
.hero { background: var(--navy); padding: 64px 20px; position: relative; overflow: hidden; width: 100%; display: flex; justify-content: center; align-items: center; }
.hero-container { width: 100%; max-width: 860px; margin: 0 auto; display: flex; flex-direction: column; align-items: center; text-align: center; }
.hero-content { width: 100%; max-width: 820px; margin: 0 auto; text-align: center; display: flex; flex-direction: column; align-items: center; }
.hero-content h1 { font-size: clamp(32px, 5.2vw, 50px); font-weight: 900; color: var(--white); line-height: 1.18; margin-bottom: 18px; letter-spacing: -0.025em; }
.hero-content h1 .hl { color: var(--orange); }
.hero-sub { font-size: clamp(15px, 2.2vw, 18px); color: rgba(255,255,255,.82); line-height: 1.6; margin: 0 auto 32px; max-width: 680px; }
.hero-cta { display: flex; flex-direction: row; justify-content: center; align-items: center; gap: 14px; width: 100%; margin-bottom: 40px; flex-wrap: wrap; }
.hero-trust { display: flex; flex-direction: row; flex-wrap: wrap; justify-content: center; align-items: center; gap: 20px 32px; padding-top: 28px; border-top: 1px solid rgba(255,255,255,.12); width: 100%; max-width: 780px; margin: 0 auto; }
.hero-trust-item { display: flex; align-items: center; gap: 10px; min-width: max-content; flex-shrink: 0; }
.hero-trust-icon { width: 34px; height: 34px; border-radius: 50%; background: rgba(255,255,255,.08); display: flex; align-items: center; justify-content: center; font-size: 14px; color: var(--orange); flex-shrink: 0; }
.hero-trust-text { display: flex; flex-direction: column; text-align: left; white-space: nowrap; }
.hero-trust-text strong { display: block; color: var(--white); font-size: 13px; font-weight: 700; line-height: 1.2; }
.hero-trust-text span { display: block; color: rgba(255,255,255,.55); font-size: 11px; line-height: 1.2; }

@media (max-width: 899px) {
  .hero { display: none !important; }
}

/* ═══ BREADCRUMB ═══ */
.breadcrumb { padding: 12px 0; font-size: 13px; color: var(--ink-soft); }
.breadcrumb ol { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; list-style: none; margin: 0; padding: 0; }
.breadcrumb li { display: flex; align-items: center; gap: 6px; }
.breadcrumb li:not(:last-child)::after { content: '›'; color: var(--border); font-weight: 700; }
.breadcrumb a { color: var(--orange); font-weight: 600; }
.breadcrumb a:hover { text-decoration: underline; }

/* ═══ CATEGORY STRIP ═══ */
.cat-strip { background: var(--white); border-bottom: 1px solid var(--border); padding: 16px 0; }
.cat-strip-inner { display: flex; gap: 12px; overflow-x: auto; scroll-behavior: smooth; -webkit-overflow-scrolling: touch; scrollbar-width: none; padding: 0 12px; }
.cat-strip-inner::-webkit-scrollbar { display: none; }
.cat-item { display: flex; align-items: center; gap: 10px; padding: 10px 16px; border-radius: var(--radius-sm); background: var(--bg); border: 1px solid var(--border); white-space: nowrap; flex-shrink: 0; transition: all .2s ease; min-height: var(--tap-target); }
.cat-item:hover { border-color: var(--orange); background: #fff; transform: translateY(-1px); }
.cat-icon { color: var(--orange); font-size: 16px; }
.cat-info .cat-name { display: block; font-size: 13.5px; font-weight: 700; color: var(--ink); }

/* ═══ SECTION HEADINGS ═══ */
.sec-heading { display: flex; align-items: center; justify-content: space-between; margin: 38px 0 24px; padding: 0 12px; }
.sec-heading h2 { font-size: clamp(22px, 3vw, 28px); font-weight: 800; }
.sec-heading h2 .hl { color: var(--orange); }

/* ═══ DEALS GRID ═══ */
.deals-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; width: 100%; min-width: 0; padding: 0 12px; }
@media (min-width: 768px) { .deals-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; padding: 0; } }
@media (min-width: 1024px) { .deals-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px; } }
@media (min-width: 1280px) { .deals-grid { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 20px; } }

/* Blogger post-wrapper normalization — NUCLEAR FIX */
#main, #Blog1, #Blog1 .widget-content, #Blog1 .blog-posts,
#Blog1 .blog-posts.hfeed, #Blog1 .post-outer, #Blog1 .post,
#Blog1 .blog-posts .post-outer-container,
#Blog1 .date-outer, #Blog1 .date-posts {
  width: 100% !important;
  max-width: 100% !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  float: none !important;
  overflow: hidden !important;
  box-sizing: border-box !important;
}
#Blog1 .deals-grid > * { min-width: 0; }

/* ═══ BLOGGER FEED RENDERER ═══ */
.feed-status { grid-column: 1 / -1; padding: 30px 16px; text-align: center; color: var(--ink-soft); background: var(--white); border: 1px solid var(--border); border-radius: var(--radius); }
.feed-actions { display: flex; justify-content: center; margin: 28px 12px 8px; }
.feed-actions .btn { min-width: 190px; }
.feed-actions.is-hidden { display: none; }

/* ═══ PRODUCT CARD ═══ */
.product-card {
  background: var(--white);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-sizing: border-box;
  transition: border-color .25s ease;
  position: relative;
  width: 100%;
  height: 100%;
  contain: layout paint;
}
.product-card:hover { border-color: var(--orange); }
.product-card > a { display: flex; flex-direction: column; height: 100%; color: inherit; text-decoration: none; }

.card-media {
  position: relative;
  background: #fff;
  padding: 0;
  aspect-ratio: 1 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-bottom: 1px solid var(--border);
  width: 100%;
  box-sizing: border-box;
}

.card-media img {
  max-width: 92%;
  max-height: 92%;
  width: auto;
  height: auto;
  object-fit: contain;
  display: block;
  transition: transform .3s ease;
}

.product-card:hover .card-media img { transform: scale(1.05); }

.card-body { padding: 10px 12px 12px; display: flex; flex-direction: column; flex: 1; gap: 6px; background: var(--white); }
.card-cat { display: flex; align-items: center; gap: 5px; font-size: 11px; text-transform: uppercase; letter-spacing: .06em; color: var(--orange); font-weight: 800; }
.card-cat .amz-icon { font-size: 13px; color: var(--orange); line-height: 1; }
.card-title { font-size: 13.5px; font-weight: 800; color: var(--ink); line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; min-height: 2.8em; text-align: center; }
.card-footer { margin-top: auto; padding-top: 8px; display: flex; justify-content: center; }
.card-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--orange);
  color: #fff;
  font-size: 11px;
  font-weight: 800;
  padding: 6px 14px;
  border-radius: 50px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

/* ═══ WHY SHOP ═══ */
.why-shop { background: var(--white); border: 1px solid var(--border); border-radius: var(--radius); padding: 32px 24px; margin: 48px 12px; }
.why-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 24px; margin-top: 20px; }
.why-item { display: flex; align-items: center; gap: 14px; }
.why-icon { width: 44px; height: 44px; border-radius: var(--radius-sm); background: var(--bg); display: flex; align-items: center; justify-content: center; font-size: 20px; color: var(--orange); flex-shrink: 0; }

/* ═══ SINGLE POST — CLEAN UNIFIED DESIGN ═══ */
.post-single { 
  background: var(--white); 
  border-radius: 16px; 
  border: 1px solid #C5E4EF; 
  padding: 32px; 
  margin: 32px 12px; 
  box-shadow: 0 2px 8px rgba(0,0,0,.04); 
  overflow: hidden; 
  word-wrap: break-word; 
  overflow-wrap: break-word;
}

.post-hero-grid { 
  display: flex; 
  flex-direction: column; 
  gap: 0; 
  align-items: stretch; 
}

.post-title { 
  font-size: clamp(24px, 4vw, 34px); 
  margin-bottom: 16px; 
  color: var(--ink);
  font-weight: 800;
  line-height: 1.25; 
  word-wrap: break-word;
  overflow-wrap: break-word;
}

.post-meta { 
  display: flex; 
  flex-wrap: wrap; 
  gap: 12px; 
  align-items: center; 
  font-size: 13px; 
  color: var(--ink-soft); 
  margin-bottom: 20px; 
}
.post-meta span { display: flex; align-items: center; gap: 6px; }

.post-hero-image { 
  overflow: hidden; 
  width: 100%;
  display: flex; 
  align-items: center; 
  justify-content: center; 
  margin: 0 auto 24px;
  padding: 0;
}
.page-view .post-hero-image { display: none; }
.post-hero-image img { 
  width: 100%; 
  height: auto; 
  display: block;
}
  object-fit: contain; 
  background: transparent; 
}

/* ═══ POST BODY CONTENT — UNIFIED CLEAN STYLE ═══ */
.post-body-content { 
  font-size: 16px; 
  line-height: 1.75; 
  color: var(--ink); 
  font-weight: 500;
  padding-top: 0; 
  overflow-wrap: break-word; 
  word-wrap: break-word; 
}
.post-body-content img { 
  max-width: 100% !important; 
  height: auto !important; 
  border-radius: 12px; 
  margin: 16px 0; 
  display: block; 
}

/* ═══ PRODUCT IMAGES ═══ */
.product-images {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.product-images .carousel-item {
  overflow: hidden;
  border-radius: 10px;
  background: #f9fafb;
}
.product-images .carousel-item img {
  transition: transform 0.3s ease;
  cursor: zoom-in;
}
.product-images .carousel-item img:hover {
  transform: scale(1.08);
  z-index: 10;
  position: relative;
}

/* ═══ ZOOM OVERLAY ON HOVER ═══ */
.zoom-container {
  position: relative;
  overflow: hidden;
  border-radius: 10px;
}
.zoom-container img {
  transition: transform 0.35s ease;
}
.zoom-container:hover img {
  transform: scale(1.15);
}

/* ═══ CUSTOMER REVIEWS GRID ═══ */
.post-body-content section div[style*="grid-template-columns:1fr 1fr"] {
  gap: 12px;
}

.post-body-content a { color: var(--orange); text-decoration: underline; font-weight: 700; }
.post-body-content h1, 
.post-body-content h2 { 
  font-size: 22px; 
  margin: 28px 0 14px; 
  font-weight: 800;
  color: var(--ink);
}
.post-body-content h3 { 
  font-size: 18px; 
  margin: 20px 0 10px; 
  font-weight: 700;
}
.post-body-content p { margin: 0 0 14px; font-weight: 500; }
.post-body-content strong, .post-body-content b { font-weight: 700; }
.post-body-content table { display: block; width: 100%; overflow-x: auto; -webkit-overflow-scrolling: touch; border-collapse: collapse; margin: 16px 0; border-radius: 12px; overflow: hidden; border: 1px solid #C5E4EF; }
.post-body-content table td, .post-body-content table th { border: 1px solid #C5E4EF; padding: 12px 16px; font-size: 14px; font-weight: 500; }
.post-body-content table th { background: #F7F8FA; font-weight: 700; }
.post-body-content iframe, .post-body-content embed, .post-body-content object { max-width: 100%; }

/* ═══ NUCLEAR OVERRIDE: Destroy ALL inline styles in post body ═══ */
.post-body-content * {
  max-width: 100% !important;
  box-sizing: border-box !important;
}

/* Remove ALL borders from sections inside post body */
.post-body-content section,
.post-body-content article,
.post-body-content div[style*="border"],
.post-body-content div[style*="border-radius"] {
  border: none !important;
  border-radius: 12px !important;
  box-shadow: 0 1px 4px rgba(0,0,0,.04) !important;
}

/* UNIFIED CARD STYLE for all sections */
.post-body-content section,
.post-body-content article {
  max-width: 100% !important;
  width: 100% !important;
  padding: 20px !important;
  margin: 0 0 16px !important;
  background: #fff !important;
  border: 1px solid #C5E4EF !important;
  border-radius: 12px !important;
  box-shadow: 0 1px 4px rgba(0,0,0,.04) !important;
}

/* Override max-width:780px and margin:0 auto */
.post-body-content [style*="max-width:780px"],
.post-body-content [style*="max-width: 780px"],
.post-body-content article[style*="max-width"] {
  max-width: 100% !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
}

.post-body-content [style*="margin:0 auto"],
.post-body-content [style*="margin: 0 auto"] {
  margin: 0 0 16px !important;
  width: 100% !important;
}

/* RESPONSIVE GRID: Desktop=multi-column, Mobile=single-column */
@media (min-width: 768px) {
  .post-body-content section[style*="grid-template-columns"],
  .post-body-content div[style*="grid-template-columns"] {
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
    gap: 16px !important;
    width: 100% !important;
  }
  .post-body-content section[style*="grid-template-columns:1fr 1fr"],
  .post-body-content div[style*="grid-template-columns:1fr 1fr"] {
    grid-template-columns: 1fr 1fr !important;
  }
  .post-body-content section[style*="repeat(4"],
  .post-body-content div[style*="repeat(4"] {
    grid-template-columns: repeat(4, 1fr) !important;
  }
}

@media (max-width: 767px) {
  .post-body-content section[style*="grid-template-columns"],
  .post-body-content div[style*="grid-template-columns"] {
    display: flex !important;
    flex-direction: column !important;
    grid-template-columns: none !important;
    gap: 12px !important;
    width: 100% !important;
  }
  .post-body-content section[style*="repeat(4"],
  .post-body-content div[style*="repeat(4"] {
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
    gap: 10px !important;
  }
  /* Product images: horizontal scroll on mobile */
  .product-images {
    display: flex !important;
    overflow-x: auto !important;
    scroll-snap-type: x mandatory !important;
    -webkit-overflow-scrolling: touch !important;
    scrollbar-width: none !important;
    gap: 12px !important;
    padding: 4px 0 !important;
    grid-template-columns: none !important;
  }
  .product-images::-webkit-scrollbar { display: none !important; }
  .product-images .carousel-item {
    flex: 0 0 75vw !important;
    scroll-snap-align: start !important;
    width: 75vw !important;
  }
}

/* All text inside post body should be bold/readable */
.post-body-content span,
.post-body-content li,
.post-body-content td {
  font-weight: 500;
}

.post-body-content li strong,
.post-body-content td strong {
  font-weight: 700;
}

/* Sticky CTA for single post on mobile */
.sticky-cta {
  display: none;
  position: fixed;
  bottom: 70px;
  left: 12px;
  right: 12px;
  z-index: 90;
  background: var(--navy);
  padding: 12px;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-lg);
  border: 1px solid rgba(255,255,255,.1);
}
.sticky-cta .btn { width: 100%; }
@media (max-width: 767px) {
  .sticky-cta { display: block; }
  .post-single { padding: 16px 12px; margin: 0; border-radius: 0; border: none; box-shadow: none; }
  .post-body-content section,
  .post-body-content article {
    padding: 16px !important;
  }
}

/* ═══ RELATED POSTS ═══ */
.related-posts { margin: 40px 12px 0; }
.related-posts h3 { font-size: 20px; margin-bottom: 20px; }
.related-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; }
@media (min-width: 768px) { .related-grid { grid-template-columns: repeat(3, 1fr); } }
.related-card { background: var(--white); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 12px; transition: all .2s ease; }
.related-card:hover { border-color: var(--orange); }
.related-card img { width: 100%; aspect-ratio: 4/3; object-fit: contain; border-radius: var(--radius-xs); margin-bottom: 8px; background: #fff; }
.related-card h4 { font-size: 13px; line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

/* ═══ FOOTER ═══ */
.site-footer { background: var(--navy); color: rgba(255,255,255,.7); margin-top: 60px; }
.footer-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 28px 40px; padding: 40px 24px 32px; max-width: var(--max-w); margin: 0 auto; }
@media (min-width: 768px) { .footer-cols { grid-template-columns: 2fr 1fr 1fr 1fr; } }
.footer-cols h4 { color: var(--white); font-size: 12px; text-transform: uppercase; margin-bottom: 12px; letter-spacing: 0.08em; font-weight: 900; border-bottom: 1px solid rgba(255,255,255,.1); padding-bottom: 8px; }
.footer-cols ul li { margin-bottom: 6px; }
.footer-cols a { color: rgba(255,255,255,.6); display: inline-flex; align-items: center; gap: 6px; font-size: 13px; transition: color .2s ease; line-height: 1.5; }
.footer-cols a:hover { color: var(--orange); }
.footer-disclaimer { max-width: var(--max-w); margin: 0 auto; padding: 0 24px 24px; font-size: 12px; color: rgba(255,255,255,.4); line-height: 1.6; border-top: 1px solid rgba(255,255,255,.06); padding-top: 20px; }
.footer-disclaimer a { color: var(--orange); }
.footer-bottom { border-top: 1px solid rgba(255,255,255,.08); padding: 20px 16px; font-size: 12px; text-align: center; color: rgba(255,255,255,.5); }

/* Mobile Bottom Nav */
.mob-bottom-nav { display: none; position: fixed; bottom: 0; left: 0; right: 0; z-index: 150; background: var(--navy); padding: 10px 0; border-top: 1px solid rgba(255,255,255,.1); }
.mob-bottom-inner { display: flex; justify-content: space-around; }
.mob-bottom-nav a { display: flex; flex-direction: column; align-items: center; gap: 4px; font-size: 11px; color: rgba(255,255,255,.7); min-height: var(--tap-target); min-width: var(--tap-target); justify-content: center; }
.mob-bottom-nav a:hover { color: var(--orange); }
@media (max-width: 767px) { .mob-bottom-nav { display: block; } body { padding-bottom: 64px; } }

/* Back to Top */
.back-to-top {
  position: fixed;
  bottom: 80px;
  right: 16px;
  z-index: 95;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--orange);
  color: #fff;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  box-shadow: var(--shadow-md);
  opacity: 0;
  visibility: hidden;
  transition: opacity .3s ease, visibility .3s ease, transform .3s ease;
  transform: translateY(10px);
}
.back-to-top.is-visible {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.back-to-top:hover { background: var(--orange-dark); transform: translateY(-2px); }

/* Infinite Scroll Spinner */
.inf-spinner {
  display: none;
  text-align: center;
  padding: 24px;
}
.inf-spinner.is-visible { display: block; }
.inf-spinner-inner {
  display: inline-block;
  width: 28px;
  height: 28px;
  border: 3px solid var(--border);
  border-top-color: var(--orange);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* ═══ MOBILE OVERRIDES ═══ */
@media (max-width: 899px) {
  .container { padding: 0 10px; }

  main#home-deals,
  main.container,
  main.single-item-page {
    max-width: 100vw;
    width: 100%;
    overflow-x: hidden;
    padding-left: 0;
    padding-right: 0;
    margin-left: 0;
    margin-right: 0;
  }

  #Blog1, #Blog1 .widget-content, #Blog1 .blog-posts,
  #Blog1 .blog-posts.hfeed, #Blog1 .post-outer, #Blog1 .post,
  #Blog1 .blog-posts .post-outer-container,
  #Blog1 .blog-posts > *,
  #Blog1 .date-outer, #Blog1 .date-posts {
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    float: none !important;
    overflow: hidden !important;
    box-sizing: border-box !important;
  }

  .deals-grid {
    display: grid !important;
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 10px !important;
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 !important;
    padding: 0 10px !important;
    overflow: hidden !important;
  }

  .product-card {
    width: 100% !important;
    max-width: 100% !important;
    overflow: hidden !important;
    margin: 0 !important;
    min-width: 0 !important;
  }
  .product-card > a { width: 100%; min-width: 0; }
  .card-body { padding: 8px; min-width: 0; }
  .card-title { font-size: 12px; min-height: auto; -webkit-line-clamp: 2; }
  .card-media { aspect-ratio: 1 / 1; padding: 0; box-sizing: border-box; }
  .card-media img { max-width: 92%; max-height: 92%; width: auto; height: auto; object-fit: contain; }

  .sec-heading { padding: 0 10px; margin: 24px 0 16px; }
  .feed-actions, .blog-pager { padding: 0 10px; margin: 20px 10px 8px; }
  .why-shop { margin: 24px 10px; padding: 20px 16px; }

  main.container.single-item-page { padding: 0 !important; margin: 0 !important; width: 100% !important; max-width: 100vw !important; }
  .post-single { 
    padding: 16px 12px; 
    margin: 0 !important; 
    border: none !important; 
    box-shadow: none !important; 
    border-radius: 0 !important; 
    width: 100% !important; 
    max-width: 100% !important; 
    overflow: hidden; 
  }
  .post-hero-image { 
    border-radius: 10px; 
    max-width: 100%;
    margin-bottom: 16px;
    padding: 0;
  }
  .page-view .post-hero-image { display: none; }
  .post-hero-image img {
    width: 100%;
    height: auto;
  }
  .post-body-content { overflow-x: hidden; word-break: break-word; font-size: 15px; }
  .post-body-content * { max-width: 100% !important; }
  .post-body-content table { display: block; overflow-x: auto; }
  .post-title { font-size: 22px; font-weight: 800; }
  .post-meta { font-size: 12px; gap: 8px; }
  .comments-section { margin-top: 24px; padding-top: 16px; }

  /* MOBILE: Override inline grid to single column */
  .post-body-content [style*="display:grid"],
  .post-body-content [style*="display: grid"] {
    display: flex !important;
    flex-direction: column !important;
    grid-template-columns: none !important;
    gap: 12px !important;
    width: 100% !important;
  }
  .post-body-content [style*="grid-template-columns"] {
    grid-template-columns: 1fr !important;
  }
  .post-body-content section[style*="repeat(4"],
  .post-body-content div[style*="repeat(4"] {
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
    gap: 10px !important;
  }
  .post-body-content article,
  .post-body-content section {
    max-width: 100% !important;
    width: 100% !important;
    padding: 16px !important;
    margin: 0 0 12px !important;
    border-radius: 10px !important;
  }
  .post-body-content [style*="max-width:780px"],
  .post-body-content [style*="max-width: 780px"] {
    max-width: 100% !important;
  }
  .post-body-content [style*="margin:0 auto"],
  .post-body-content [style*="margin: 0 auto"] {
    margin: 0 0 12px !important;
    width: 100% !important;
  }
  .post-body-content [style*="padding:24px"],
  .post-body-content [style*="padding: 24px"] {
    padding: 16px !important;
  }
  .post-body-content [style*="padding:20px"],
  .post-body-content [style*="padding: 20px"] {
    padding: 14px !important;
  }
  .post-body-content img {
    max-width: 100% !important;
    height: auto !important;
    object-fit: contain !important;
  }

  .search-form {
    border-radius: 50px;
    border: 2px solid var(--orange) !important;
    background: rgba(255,255,255,.08);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    max-width: 100%;
    overflow: hidden;
  }
  .search-form input { border-radius: 50px 0 0 50px; padding: 10px 14px; }
  .search-form button { background: var(--orange); border-radius: 0 50px 50px 0; color: #fff; width: 44px; }

  .product-card:hover { border-color: var(--border) !important; }
  .product-card:hover .card-media img { transform: none !important; }
  .cat-item:hover { transform: none !important; border-color: var(--border) !important; }
  .btn:hover { transform: none !important; }

  .breadcrumb { font-size: 12px; padding: 8px 10px; }
  .related-posts { margin: 24px 10px 0; }
  .related-grid { gap: 10px; }
}

/* Pager */
.blog-pager { display: flex; justify-content: space-between; gap: 12px; margin: 32px 12px; }
.blog-pager a { font-weight: 600; font-size: 14px; padding: 12px 20px; border: 1.5px solid var(--border); border-radius: var(--radius-sm); background: var(--white); transition: all .2s; }
.blog-pager a:hover { border-color: var(--orange); color: var(--orange); }

/* Comments */
.comments-section { margin-top: 40px; border-top: 1px solid var(--border); padding-top: 24px; }
.comments-section h4 { font-size: 18px; margin-bottom: 20px; }

@media print {
  .site-header, .hero, .cat-strip, .mob-bottom-nav, .back-to-top, .sticky-cta, .mob-drawer, .mob-overlay { display: none !important; }
  .post-single { box-shadow: none; border: 1px solid #ccc; }
}

b:if.script:
//
(function() {
  var labels = [<b:loop values='data:post.labels' var='label'>"<data:label.name/>",</b:loop>];
  var currentUrl = "<data:post.url/>";
  var feedUrl = "/feeds/posts/default/-/" + encodeURIComponent(labels[0]) + "?alt=json-in-script&amp;max-results=4&amp;callback=relatedCallback";
  window.relatedCallback = function(data) {
    var entries = data.feed.entry || [];
    var html = '';
    var count = 0;
    for (var i = 0; i < entries.length && count < 3; i++) {
      var entry = entries[i];
      var link = '';
      for (var j = 0; j < entry.link.length; j++) {
        if (entry.link[j].rel == 'alternate') { link = entry.link[j].href; break; }
      }
      if (link == currentUrl) continue;
      var title = entry.title.$t;
      var img = '';
      if (entry.media$thumbnail) {
        img = entry.media$thumbnail.url.replace(/\/s72-c/, '/s400-c');
      } else {
        img = 'https://placehold.co/400x300/F7F8FA/999?text=NestDeal';
      }
      html += '<a class="related-card" href="' + link + '"><img src="' + img + '" alt="' + title + '" loading="lazy" decoding="async"/>' + '<h4>' + title + '</h4></a>';
      count++;
    }
    if (html) {
      document.getElementById('relatedGrid').innerHTML = html;
    } else {
      document.getElementById('relatedPosts').style.display = 'none';
    }
  };
  var script = document.createElement('script');
  script.src = feedUrl;
  document.head.appendChild(script);
})();
//

body.script:
//
(function() {
  'use strict';

  /* ═══ MOBILE MENU ═══ */
  var mobToggle = document.getElementById('mobMenuToggle');
  var mobDrawer = document.getElementById('mobDrawer');
  var mobOverlay = document.getElementById('mobOverlay');
  var mobClose = document.getElementById('mobDrawerClose');

  function openMenu() {
    if (mobDrawer) { mobDrawer.classList.add('is-open'); mobDrawer.setAttribute('aria-hidden', 'false'); document.body.style.overflow = 'hidden'; }
    if (mobOverlay) { mobOverlay.classList.add('is-open'); mobOverlay.setAttribute('aria-hidden', 'false'); }
  }
  function closeMenu() {
    if (mobDrawer) { mobDrawer.classList.remove('is-open'); mobDrawer.setAttribute('aria-hidden', 'true'); document.body.style.overflow = ''; }
    if (mobOverlay) { mobOverlay.classList.remove('is-open'); mobOverlay.setAttribute('aria-hidden', 'true'); }
  }
  if (mobToggle) mobToggle.addEventListener('click', openMenu);
  if (mobOverlay) mobOverlay.addEventListener('click', closeMenu);
  if (mobClose) mobClose.addEventListener('click', closeMenu);

  // Close on swipe right
  var touchStartX = 0;
  if (mobDrawer) {
    mobDrawer.addEventListener('touchstart', function(e){ touchStartX = e.changedTouches[0].screenX; }, {passive:true});
    mobDrawer.addEventListener('touchend', function(e){ if (e.changedTouches[0].screenX - touchStartX > 60) closeMenu(); }, {passive:true});
  }
  // Close on Escape key
  document.addEventListener('keydown', function(e) { if (e.key === 'Escape') closeMenu(); });

  /* ═══ BACK TO TOP ═══ */
  var backToTop = document.getElementById('backToTop');
  if (backToTop) {
    window.addEventListener('scroll', function() {
      if (window.scrollY > 300) backToTop.classList.add('is-visible');
      else backToTop.classList.remove('is-visible');
    }, {passive:true});
    backToTop.addEventListener('click', function() { window.scrollTo({top:0, behavior:'smooth'}); });
  }

  /* ═══ INFINITE SCROLL ═══ */
  // Only run on index pages (not single posts or static pages)
  if (!document.querySelector('.single-item-page')) {
    var grid = document.getElementById('nestdeal-products');
    var feedActions = document.getElementById('feedActions');
    var loadMoreBtn = document.getElementById('loadMoreBtn');
    var infSpinner = document.getElementById('infSpinner');
    var nextUrl = loadMoreBtn ? loadMoreBtn.href : null;
    var isLoading = false;
    var sentinel = document.createElement('div');
    sentinel.id = 'inf-scroll-sentinel';
    sentinel.style.cssText = 'height:2px;margin:0;';

    if (grid && nextUrl) {
      // Insert sentinel after grid
      grid.parentNode.insertBefore(sentinel, grid.nextSibling);
      // Move spinner after sentinel
      if (infSpinner) grid.parentNode.insertBefore(infSpinner, sentinel.nextSibling);

      function loadMore() {
        if (isLoading || !nextUrl) return;
        isLoading = true;
        if (infSpinner) infSpinner.classList.add('is-visible');
        if (feedActions) feedActions.style.display = 'none';

        fetch(nextUrl)
          .then(function(r) { return r.text(); })
          .then(function(html) {
            var parser = new DOMParser();
            var doc = parser.parseFromString(html, 'text/html');
            var newGrid = doc.getElementById('nestdeal-products');
            var newCards = newGrid ? newGrid.querySelectorAll('.product-card') : [];

            newCards.forEach(function(card) { grid.appendChild(card); });

            var newBtn = doc.querySelector('#loadMoreBtn');
            if (newBtn) {
              nextUrl = newBtn.href;
              if (feedActions) feedActions.style.display = 'flex';
            } else {
              nextUrl = null;
              if (feedActions) feedActions.style.display = 'none';
              if (infSpinner) {
                infSpinner.innerHTML = '<p style="text-align:center;color:var(--ink-soft);padding:20px;font-size:14px;">No more deals to load.</p>';
                infSpinner.classList.add('is-visible');
              }
            }

            isLoading = false;
            if (infSpinner && nextUrl) infSpinner.classList.remove('is-visible');

            // Update URL for analytics
            if (window.history && window.history.replaceState && nextUrl) {
              window.history.replaceState({}, '', nextUrl);
            }
          })
          .catch(function(err) {
            console.error('Infinite scroll error:', err);
            isLoading = false;
            if (infSpinner) infSpinner.classList.remove('is-visible');
            if (feedActions) feedActions.style.display = 'flex';
          });
      }

      if ('IntersectionObserver' in window) {
        var observer = new IntersectionObserver(function(entries) {
          if (entries[0].isIntersecting && !isLoading && nextUrl) loadMore();
        }, { rootMargin: '400px' });
        observer.observe(sentinel);
      } else {
        // Fallback: show button
        if (feedActions) feedActions.style.display = 'flex';
      }
    }
  }

  /* ═══ STICKY CTA HIDE ON SCROLL DOWN (Single Post) ═══ */
  var stickyCta = document.getElementById('stickyCta');
  if (stickyCta) {
    var lastScroll = 0;
    window.addEventListener('scroll', function() {
      var currentScroll = window.scrollY;
      if (currentScroll > lastScroll && currentScroll > 200) {
        stickyCta.style.transform = 'translateY(120%)';
        stickyCta.style.transition = 'transform 0.3s ease';
      } else {
        stickyCta.style.transform = 'translateY(0)';
      }
      lastScroll = currentScroll;
    }, {passive:true});
  }

  /* ═══ EXTRACT PRODUCT IMAGE FROM POST BODY ═══ */
  var heroImage = document.querySelector('.post-hero-image img');
  if (heroImage && heroImage.src && heroImage.src.indexOf('placehold.co') !== -1) {
    var postBody = document.querySelector('.post-body-content');
    if (postBody) {
      var allImages = postBody.querySelectorAll('img');
      for (var i = 0; i < allImages.length; i++) {
        var img = allImages[i];
        var src = img.getAttribute('src') || '';
        if (src && src.indexOf('placehold.co') === -1 && src.indexOf('blogblog.com') === -1 && src.indexOf('blogger.googleusercontent.com') === -1) {
          heroImage.src = src;
          heroImage.alt = img.alt || heroImage.alt;
          img.style.display = 'none';
          break;
        }
      }
    }
  }

})();
//
